from pysat.solvers import Glucose3
from pysat.card import CardEnc

N = 27

# Pre-assigned positions
fixed = {9: 23, 12: 13, 18: 1, 21: 21, 26: 14}

# Create SAT solver
solver = Glucose3()

# Variable encoding: x[r][c] = True means queen at row r, column c
# Variable index: r * N + c + 1 (1-indexed for SAT)
def var(r, c):
    return r * N + c + 1

# Constraint 1: Each row has exactly one queen
for r in range(N):
    # At least one queen in row r
    row_vars = [var(r, c) for c in range(N)]
    solver.add_clause(row_vars)
    # At most one queen in row r (pairwise)
    for c1 in range(N):
        for c2 in range(c1 + 1, N):
            solver.add_clause([-var(r, c1), -var(r, c2)])

# Constraint 2: Each column has exactly one queen
for c in range(N):
    # At least one queen in column c
    col_vars = [var(r, c) for r in range(N)]
    solver.add_clause(col_vars)
    # At most one queen in column c (pairwise)
    for r1 in range(N):
        for r2 in range(r1 + 1, N):
            solver.add_clause([-var(r1, c), -var(r2, c)])

# Constraint 3: No two queens on same diagonal (row - col = constant)
# Diagonals with row - col = d, where d ranges from -(N-1) to (N-1)
for d in range(-(N-1), N):
    diag_vars = []
    for r in range(N):
        c = r - d
        if 0 <= c < N:
            diag_vars.append(var(r, c))
    # At most one queen on this diagonal
    for i in range(len(diag_vars)):
        for j in range(i + 1, len(diag_vars)):
            solver.add_clause([-diag_vars[i], -diag_vars[j]])

# Constraint 4: No two queens on same anti-diagonal (row + col = constant)
# Anti-diagonals with row + col = s, where s ranges from 0 to 2*(N-1)
for s in range(2 * N - 1):
    anti_diag_vars = []
    for r in range(N):
        c = s - r
        if 0 <= c < N:
            anti_diag_vars.append(var(r, c))
    # At most one queen on this anti-diagonal
    for i in range(len(anti_diag_vars)):
        for j in range(i + 1, len(anti_diag_vars)):
            solver.add_clause([-anti_diag_vars[i], -anti_diag_vars[j]])

# Constraint 5: Fixed positions
for r, c in fixed.items():
    solver.add_clause([var(r, c)])

# Solve
if solver.solve():
    model = solver.get_model()
    solution = [0] * N
    for r in range(N):
        for c in range(N):
            if var(r, c) in model:
                solution[r] = c
                break
    print("Solution found:", solution)

    # Verify solution
    valid = True
    for r in range(N):
        for r2 in range(r + 1, N):
            if solution[r] == solution[r2]:
                print(f"Column conflict: rows {r} and {r2}")
                valid = False
            if abs(solution[r] - solution[r2]) == abs(r - r2):
                print(f"Diagonal conflict: rows {r} and {r2}")
                valid = False

    if valid:
        print("Solution is valid!")
    else:
        print("Solution is invalid!")
else:
    print("UNSATISFIABLE")

solver.delete()
